    # Each source emits a horizontal ray through its center. At every other 2
    # on that ray, put 1s on the immediately adjacent cells along the ray's axis,
    # and on the two adjacent rows, matching the cross-like junctions in demos.
    for r,c in centers:
        for j in range(w):
            if grid[r][j]==0:
                out[r][j]=1
        for j in range(w):
            if grid[r][j]==2 and j!=c:
                for y in (r-1,r+1):
                    for x in (j-1,j,j+1):
                        if 0<=y<h and 0<=x<w and grid[y][x]==0:
                            out[y][x]=1
    return out
